// Supplied Task A checks. Students do not edit this file.
#include <cmath>
#include <iostream>
#include <sstream>
#include <string>
#include "../grade_item.h"

bool report(const char* name, bool ok)
{
    std::cout << (ok ? "PASS " : "FAIL ") << name << std::endl;
    return ok;
}

bool same(double a, double b)
{
    return std::fabs(a - b) < 1e-9;
}

// Runs item.print() and returns what it printed.
std::string printed(const GradeItem& item)
{
    std::ostringstream text;
    std::streambuf* old = std::cout.rdbuf(text.rdbuf());
    item.print();
    std::cout.rdbuf(old);
    return text.str();
}

int main()
{
    bool all = true;

    GradeItem homework("Homework 1", 9, 10);
    if (!report("A01 constructor and getters",
        homework.getName() == "Homework 1" && same(homework.getEarned(), 9) &&
        homework.getPossible() == 10)) all = false;

    GradeItem low("Low", -2, 10);
    GradeItem high("High", 12, 10);
    GradeItem zero("Zero", 0, 10);
    GradeItem full("Full", 10, 10);
    if (!report("A02 earned is kept in [0, possible]",
        same(low.getEarned(), 0) && same(high.getEarned(), 10) &&
        same(zero.getEarned(), 0) && same(full.getEarned(), 10))) all = false;

    GradeItem reading("Reading", 7.5, 8);
    if (!report("A03 finalPoints",
        same(homework.finalPoints(), 9) && same(reading.finalPoints(), 7.5) &&
        same(high.finalPoints(), 10))) all = false;

    std::string line1 = printed(homework);
    std::string line2 = printed(reading);
    if (!report("A04 print", line1 == "Homework 1: 9.0 / 10\n" &&
                              line2 == "Reading: 7.5 / 8\n"))
    {
        all = false;
        std::cout << "  expected: Homework 1: 9.0 / 10\n";
        std::cout << "  printed:  " << line1;
        std::cout << "  expected: Reading: 7.5 / 8\n";
        std::cout << "  printed:  " << line2;
    }

    return all ? 0 : 1;
}
